ice-kit v0.0.9","tree":{"sha":"4fcd9a814382e4a3cc33c27efc6b25daee8fd7c3","url":"https://api.github.com/repos/portable-genai/disputes-chargebacks-manager/git/trees/4fcd9a814382e4a3cc33c27efc6b25daee8fd7c3"},"url":"https://api.github.com/repos/portable-genai/disputes-chargebacks-manager/git/commits/d4f8f7bf4cf09588a623374ef898bf6ad8a5f646","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/disputes-chargebacks-manager/commit/d4f8f7bf4cf09588a623374ef898bf6ad8a5f646","node_id":"C_kwDOUAh_u9oAKGQ0ZjhmN2JmNGNmMDk1ODhhNjIzMzc0ZWY4OThiZjZhZDhhNWY2NDY","parents":[{"html_url":"https://github.com/portable-genai/disputes-chargebacks-manager/commit/dc389977e0e1bf761f2af9992e2e0ad09858a52c","sha":"dc389977e0e1bf761f2af9992e2e0ad09858a52c","url":"https://api.github.com/repos/portable-genai/disputes-chargebacks-manager/commits/dc389977e0e1bf761f2af9992e2e0ad09858a52c"}],"sha":"d4f8f7bf4cf09588a623374ef898