canonical tests/unit/test_console_matches_api.py now skips fetch(API + ...) calls that sit\ninside // or /* */ comments, so a commented-out example cannot be read as a live call. Copied\nverbatim; it still fails on the old console and passes on this one.","tree":{"sha":"284c5d17b49fecfc3ffb7312f173bbdca37e6744","url":"https://api.github.com/repos/portable-genai/ai-act-conformity-pack/git/trees/284c5d17b49fecfc3ffb7312f173bbdca37e6744"},"url":"https://api.github.com/repos/portable-genai/ai-act-conformity-pack/git/commits/23e1709dffbe9c921fa3698811bdaa5002d9b200","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/ai-act-conformity-pack/commit/23e1709dffbe9c921fa3698811bdaa5002d9b200","node_id":"C_kwDOUAiAadoAKDIzZTE3MDlkZmZiZTljOTIxZmEzNjk4ODExYmRhYTUwMDJkOWIyMDA","parents":[{"html_url":"https://github.com/portable-genai/ai-act-conformity-pack/commit/946917b0cbc0ba14fee5d2476d1fb100f5cc4bdf",