-only\nchange; npm audit reports no vulnerabilities.","tree":{"sha":"082567012b11494329e58fa44ff6640e78018b23","url":"https://api.github.com/repos/portable-genai/conflicts-gifts-pad-register/git/trees/082567012b11494329e58fa44ff6640e78018b23"},"url":"https://api.github.com/repos/portable-genai/conflicts-gifts-pad-register/git/commits/862fa1435470970931cd0e71b4d75a2569eff487","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/conflicts-gifts-pad-register/commit/862fa1435470970931cd0e71b4d75a2569eff487","node_id":"C_kwDOUAiAs9oAKDg2MmZhMTQzNTQ3MDk3MDkzMWNkMGU3MWI0ZDc1YTI1NjllZmY0ODc","parents":[{"html_url":"https://github.com/portable-genai/conflicts-gifts-pad-register/commit/bb1b77254e2599c4611d79859b1d798d2291d4b7","sha":"bb1b77254e2599c4611d79859b1d798d2291d4b7","url":"https://api.github.com/repos/portable-genai/conflicts-gifts-pad-register/commits/bb1b77254e2599c4611d79859b1d798d2291d4b7"