patch\n- dependency-name: \"@types/react\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/react-dom\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n...\n\nSigned-off-by: dependabot[bot] <support@github.com>","tree":{"sha":"ab520175c6de263fd9bb0732262e8fb6067357be","url":"https://api.github.com/repos/portable-genai/consumer-duty-monitoring/git/trees/ab520175c6de263fd9bb0732262e8fb6067357be"},"url":"https://api.github.com/repos/portable-genai/consumer-duty-monitoring/git/commits/f371788e419688dd50b0ec60e551ac929156bc13","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/consumer-duty-monitoring/commit/f371788e419688dd50b0ec60e551ac929156bc13","node_id":"C_kwDO