upport@github.com>","tree":{"sha":"c7503027e00c73c7e0040dfc1df95f5fd9cab158","url":"https://api.github.com/repos/portable-genai/trade-comms-surveillance/git/trees/c7503027e00c73c7e0040dfc1df95f5fd9cab158"},"url":"https://api.github.com/repos/portable-genai/trade-comms-surveillance/git/commits/ae9f919e404051365cfeeee43b2c6a749a64d5ad","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/trade-comms-surveillance/commit/ae9f919e404051365cfeeee43b2c6a749a64d5ad","node_id":"C_kwDOUAiEhtoAKGFlOWY5MTllNDA0MDUxMzY1Y2ZlZWVlNDNiMmM2YTc0OWE2NGQ1YWQ","parents":[{"html_url":"https://github.com/portable-genai/trade-comms-surveillance/commit/d819ed8a4b8c6d87c1b7ed2d1d53168aad979cf0","sha":"d819ed8a4b8c6d87c1b7ed2d1d53168aad979cf0","url":"https://api.github.com/repos/portable-genai/trade-comms-surveillance/commits/d819ed8a4b8c6d87c1b7ed2d1d53168aad979cf0"}],"sha":"ae9f919e404051365cfeeee43b2c6a749a64d5ad","u