cy-version: 16.3.5\n  dependency-type: direct:production\n  update-type: version-update:semver-patch\n  dependency-group: npm-minor-patch\n- dependency-name: react\n  dependency-version: 19.3.0\n  dependency-type: direct:production\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/react\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: react-dom\n  dependency-version: 19.3.0\n  dependency-type: direct:production\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/react-dom\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/node\"\n  dependency-version: 26.5.1\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/react\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n- dependency-name: \"@types/react-dom\"\n  dependency-version: 19.3.0\n  dependency-type: direct:development\n  update-type: version-update:semver-minor\n  dependency-group: npm-minor-patch\n...\n\nSigned-off-by: dependabot[bot] <support@github.com>","tree":{"sha":"fcd407cbf50e1e57ed1867ed144e8810297e8937","url":"https://api.github.com/repos/portable-genai/conversation-qa-scorecard/git/trees/fcd407cbf50e1e57ed1867ed144e8810297e8937"},"url":"https://api.github.com/repos/portable-genai/conversation-qa-scorecard/git/commits/2471bdc48091815a00fd2c8e4dc66f1515831227","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","ev