upport@github.com>","tree":{"sha":"6918e18c773ebe32c772cb727364f8d640a8a1f3","url":"https://api.github.com/repos/portable-genai/code-api-migration/git/trees/6918e18c773ebe32c772cb727364f8d640a8a1f3"},"url":"https://api.github.com/repos/portable-genai/code-api-migration/git/commits/3af718a0eea09ebab258c60d8274c50116bbd9c0","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/code-api-migration/commit/3af718a0eea09ebab258c60d8274c50116bbd9c0","node_id":"C_kwDOUAiG4doAKDNhZjcxOGEwZWVhMDllYmFiMjU4YzYwZDgyNzRjNTAxMTZiYmQ5YzA","parents":[{"html_url":"https://github.com/portable-genai/code-api-migration/commit/519ad12e52ae5faeab7b4f293f826bf840d39788","sha":"519ad12e52ae5faeab7b4f293f826bf840d39788","url":"https://api.github.com/repos/portable-genai/code-api-migration/commits/519ad12e52ae5faeab7b4f293f826bf840d39788"}],"sha":"3af718a0eea09ebab258c60d8274c50116bbd9c0","url":"https://api.github.com/re