ves; the repository''s own gate is green.","tree":{"sha":"268b821fb7ad027114c4e0eed2fd1b3dd8f1d670","url":"https://api.github.com/repos/portable-genai/hr-policy-answers/git/trees/268b821fb7ad027114c4e0eed2fd1b3dd8f1d670"},"url":"https://api.github.com/repos/portable-genai/hr-policy-answers/git/commits/ab97323c3b250620ff5f382283c62d5c37bb11cf","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/72717?v=4","events_url":"https://api.github.com/users/ashishawasthi/events{/privacy}","followers_url":"https://api.github.com/users/ashishawasthi/followers","following_url":"https://api.github.com/users/ashishawasthi/following{/other_user}","gists_url":"https://api.github.com/users/ashishawasthi/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/ashishawasthi","id":72717,"login":"ashishawasthi","node_id":"MDQ6VXNlcjcyNzE3","organizations_url":"https://api.github.com/users/ashishawasthi/orgs","received_events_url":"https://api.github.com/users/ashishawasthi/received_events","repos_url":"https://api.github.com/users/ashishawasthi/repos","site_admin":false,"starred_url":"https://api.github.com/users/ashishawasthi/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/ashishawasthi/subscriptions","type":"User","url":"https://api.github.com/users/ashishawasthi","user_view_type":"public"},"html_url":"https://github.com/portable-genai/hr-policy-answers/commit/ab97323c3b250620ff5f382283c62d5c37bb11cf","node_id":"C_kwDOUAiIiNoAKGFiOTczMjNjM2IyNTA2MjBmZjVmMzgyMjgzYzYyZDVjMzdiYjExY2Y","parents":[{"html_url":"https://github.com/portable-genai/hr-policy-answers/commit/0beca26bbcf91f2d1c776b0067b889a3383708d2","sha":"0beca26bbcf91f2d1c776b0067b889a3383708d2","url":"https://api.github.com/repos/portable-genai/hr-policy-answers/commits/0beca26bbcf91f2d1c776b0067b889a3383708d2"}],"sha":"ab97323c3b250620ff5f382283c62d5c37bb11cf","url":"https:/